-- 27 topics, 6 roles.

begin;

insert into public.training_role (slug, name, sort_order)
select r.slug, r.name, r.sort_order
from jsonb_to_recordset($seed_json$[{"slug":"project-engineer","name":"Project Engineer","sort_order":0},{"slug":"assistant-project-manager","name":"Assistant Project Manager","sort_order":1},{"slug":"project-manager","name":"Project Manager","sort_order":2},{"slug":"estimator","name":"Estimator","sort_order":3},{"slug":"assistant-superintendent","name":"Assistant Superintendent","sort_order":4},{"slug":"superintendent","name":"Superintendent","sort_order":5}]$seed_json$::jsonb) as r(slug text, name text, sort_order integer)
on conflict (slug) do nothing;

